// features/lifecycle.feature: Sign-in ignores the case of the email address
import { PASSWORD, USERS, expect, expectStatus, test } from "../../fixtures";

test("sign-in ignores the case of the email address", { tag: "@LIF-11" }, async ({ request }) => {
  // Arrange: the scenario's mixed-case spelling ("Member@Northwind.TEST") of the seeded member's address
  const [local = "", domain = ""] = USERS.member.split("@");
  const [host = "", tld = ""] = domain.split(".");
  const mixedCaseEmail = `${local.charAt(0).toUpperCase()}${local.slice(1)}@${host.charAt(0).toUpperCase()}${host.slice(1)}.${tld.toUpperCase()}`;
  expect(mixedCaseEmail, "the sign-in address differs only by case").not.toBe(USERS.member);
  expect(mixedCaseEmail.toLowerCase(), "seeded member's email, lowercased").toBe(USERS.member);

  // Act
  const response = await request.post("/api/auth/login", {
    data: { email: mixedCaseEmail, password: PASSWORD },
  });

  // Assert
  const body = await expectStatus(response, 200);
  expect(body.user.email).toBe(USERS.member);

  const me = await expectStatus(
    await request.get("/api/me", { headers: { Authorization: `Bearer ${body.access_token}` } }),
    200,
  );
  expect(me.email).toBe(USERS.member);
});
